using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.ENC.Preguntas{    [SwaggerSchema("Modelo de lectura de un Pregunta")]    [GraphQLDescription("Objeto que representa un Pregunta existente.")]    public class clReadPreguntas    {        [SwaggerSchema("Identificador único del Pregunta")]        [GraphQLDescription("Identificador único del Pregunta")]        public int? PreguntaID { get; set; }        [SwaggerSchema("EncuestaID")]        [GraphQLDescription("EncuestaID")]        public int? EncuestaID { get; set; }        [SwaggerSchema("Texto")]        [GraphQLDescription("Texto")]        public string? Texto { get; set; } = default!;        [SwaggerSchema("TipoPreguntaID")]        [GraphQLDescription("TipoPreguntaID")]        public int? TipoPreguntaID { get; set; }        [SwaggerSchema("Orden")]        [GraphQLDescription("Orden")]        public int? Orden { get; set; }        [SwaggerSchema("Requerida")]        [GraphQLDescription("Requerida")]        public bool? Requerida { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Pregunta")]    [GraphQLDescription("Input para crear un Pregunta.")]    public class clCreatePreguntas    {        [GraphQLNonNullType] [SwaggerSchema("EncuestaID")]        [GraphQLDescription("EncuestaID")]        public int EncuestaID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Texto")]        [GraphQLDescription("Texto")]        public string Texto { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("TipoPreguntaID")]        [GraphQLDescription("TipoPreguntaID")]        public int TipoPreguntaID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Orden")]        [GraphQLDescription("Orden")]        public int Orden { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Requerida")]        [GraphQLDescription("Requerida")]        public bool Requerida { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Pregunta")]    [GraphQLDescription("Input para actualizar parcialmente un Pregunta.")]    public class clUpdatePreguntas    {        [SwaggerSchema("Identificador único del Pregunta")]        [GraphQLDescription("Identificador único del Pregunta")]        public int? PreguntaID { get; set; }        [SwaggerSchema("EncuestaID")]        [GraphQLDescription("EncuestaID")]        public int? EncuestaID { get; set; }        [SwaggerSchema("Texto")]        [GraphQLDescription("Texto")]        public string? Texto { get; set; }        [SwaggerSchema("TipoPreguntaID")]        [GraphQLDescription("TipoPreguntaID")]        public int? TipoPreguntaID { get; set; }        [SwaggerSchema("Orden")]        [GraphQLDescription("Orden")]        public int? Orden { get; set; }        [SwaggerSchema("Requerida")]        [GraphQLDescription("Requerida")]        public bool? Requerida { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}